foreach ($plan['carrosseis'] as $c) {
    $bad = array_filter(array_merge($c['urls'], $c['jpgs']), fn($u) => !$ok($u));
    if ($bad) { $out[] = "CARROSSEL|MIDIA_ERRO|{$c['slug']}|" . count($bad); continue; }
    // Instagram recebe as lâminas em vídeo (com música); Threads recebe as mesmas lâminas em JPG.
    foreach ([['instagram', $c['when'], $c['urls']], ['threads', gmdate('Y-m-d H:i:s', strtotime($c['when'] . ' UTC') + 1800), $c['jpgs']]] as [$canal, $when, $urls]) {
        $json = json_encode($urls);
        $cE->execute([$canal, $json]);
        if ($cE->fetchColumn()) { $out[] = strtoupper($canal) . "_CARROSSEL|IGNORADO|{$c['slug']}"; continue; }
        $leg = $canal === 'threads' ? mb_substr(explode("\n\n#", $c['caption'])[0], 0, 480) : $c['caption'];
        $ins->execute([$canal, 'carousel', $canal === 'threads' ? 'imagem' : 'video', $leg, $urls[0], $json, $when, 'pendente', null]);
        $out[] = strtoupper($canal) . "_CARROSSEL|OK|{$when}|{$c['slug']}";
    }
}
$ja = $pdo->query("SELECT id FROM social_auto_reply_rules WHERE UPPER(palavra_chave)='FABRIC' LIMIT 1")->fetchColumn();
if ($ja) $out[] = "REGRA_FABRIC|JA_EXISTE|id=$ja";
else {
    $msg = "Oi! Aqui está o curso de Microsoft Fabric da TECH SANTOS BR: https://techsantos.com.br/curso-microsoft-fabric.php?utm_source=instagram&utm_medium=dm&utm_campaign=comente_fabric\n\n"
         . "São 82 aulas com teoria completa em 15 módulos, do OneLake ao Lakehouse, Warehouse e pipelines. R$ 129,90, acesso vitalício.\n\nQualquer dúvida, é só responder aqui.";
    $pdo->prepare('INSERT INTO social_auto_reply_rules (palavra_chave, mensagem, ativo, prioridade) VALUES (?, ?, 1, 5)')->execute(['FABRIC', $msg]);
    $out[] = "REGRA_FABRIC|CRIADA|id=" . $pdo->lastInsertId();
}
echo implode("\n", $out) . "\n";
